import{_ as a,o,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Status de compilação e recuperação do TikTools 4.2.2","description":"","frontmatter":{"title":"Status de compilação e recuperação do TikTools 4.2.2","docId":"releases.4.2.2","translationKey":"releases.4.2.2","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2a82a33b45407681d8d052a8a16e40dbc83f6889b3e4874cf05f95cc4aa44896","translationRevision":"a8749464e43a2f7775384c869ba30ab25bdbbd4303e59b58a26acf097b7e7b53","order":40},"headers":[],"relativePath":"pt/releases/4.2.2.md","filePath":"pt/releases/4.2.2.md","lastUpdated":1794611623000}'),i={name:"pt/releases/4.2.2.md"};function t(d,e,n,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="tiktools-422" tabindex="-1">TikTools 4.2.2 <a class="header-anchor" href="#tiktools-422" aria-label="Permalink to &quot;TikTools 4.2.2 {#tiktools-422}&quot;">​</a></h1><h2 id="goal-publication-status-and-prerequisites" tabindex="-1">Objetivo, status de publicação e pré-requisitos <a class="header-anchor" href="#goal-publication-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, status de publicação e pré-requisitos {#goal-publication-status-and-prerequisites}&quot;">​</a></h2><p>Use estas notas para revisar as alterações implementadas em Variables e as verificações restantes da versão. Status informado em 13 de novembro de 2026: <strong>a compilação do aplicativo e as verificações de CI passaram; os instaladores Linux agora são empacotados com sucesso e o empacotamento Windows passou, mas a verificação de inicialização do AppImage falhou por uma dependência XKB de execução ausente e a 4.2.2 não foi publicada</strong>. Não se afirma publicação bem-sucedida de instaladores, verificação de somas de arquivos enviados nem promoção do feed de atualização.</p><p>A compilação executa em <code>hernan-lc/TikTools-app</code> com <code>RELEASE_REPO=nglmercer/TikTools-app</code> como destino pretendido de publicação. Artefatos das candidatas 4.2.1 existentes continuam separados. Para uma versão de teste disponível, use a <a href="./4.2.1-rc.3.html">versão preliminar RC3 publicada</a>; confira a <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versões</a> para artefatos realmente disponíveis para download.</p><p>Esses recursos de Cloud e colaboração continuam experimentais. Testar código/candidata exige um host correspondente compilado separadamente, perfil isolado, Variables não secretas salvas, sessão/consentimento atuais do Cloud e a ponte nativa anunciada. Consulte a <a href="./../developer/setup.html">configuração de desenvolvimento</a>.</p><h2 id="implemented-variables-changes" tabindex="-1">Alterações implementadas em Variables <a class="header-anchor" href="#implemented-variables-changes" aria-label="Permalink to &quot;Alterações implementadas em Variables {#implemented-variables-changes}&quot;">​</a></h2><p>Variables usa o painel compartilhado Changes. Send trata apenas valores nativos salvos selecionados; download atualiza apenas o cache. Aplicar um valor revisado do Cloud e retirar sua cópia do Cloud são ações separadas. A retirada mantém o valor local e a classificação secreta. Rascunhos locais não salvos devem ser salvos ou descartados primeiro, e hosts antigos sem a ponte ocultam o controle.</p><p>O host verifica sessão exata, consentimento, revisão local e comparação de destino. Edições enfileiradas podem ser substituídas ou canceladas. A recuperação protegida por época trata envios incertos e retirada depois que um valor se torna secreto sem reproduzir seu valor anterior. As gerações de decisão avançam após a confirmação. Variables não marcadas e filas de outras seções ficam fora do envio selecionado.</p><p>Inteiros grandes mantêm o texto nativo exato durante edição no navegador e comparação/adoção. Salvar uma variável não relacionada preserva o texto de inteiros intocados. Os tipos continuam texto, número, booleano, lista e segredo local. Valores secretos ou bloqueados não têm comparação de valor, controle de envio nem de adoção. Este adaptador não tem controles de mesclagem de campos, força, histórico ou sincronização automática.</p><h2 id="review-steps-and-expected-result" tabindex="-1">Etapas de revisão e resultado esperado <a class="header-anchor" href="#review-steps-and-expected-result" aria-label="Permalink to &quot;Etapas de revisão e resultado esperado {#review-steps-and-expected-result}&quot;">​</a></h2><ol><li>Em uma candidata isolada correspondente, salve um valor de texto inofensivo como <code>demoGreeting = &quot;Olá&quot;</code>. Salvar sozinho deve permanecer local.</li><li>Abra Variables → Changes quando o host anunciar suporte. Revise a comparação local/Cloud salva e escolha apenas a linha desejada para Send.</li><li>Trate download como atualização de cache. Revise e use Apply separadamente antes de esperar que o valor local mude.</li><li>Use retirada explícita para remover uma cópia do Cloud. O valor local e sua classificação secreta devem permanecer intactos.</li><li>Se sessão, consentimento, revisão ou destino mudar, atualize a comparação e revise novamente. Resolva um resultado incerto pelo caminho de recuperação existente em vez de repetir um envio como nova operação.</li></ol><p>Esses são comportamentos esperados do código, não resultados de aceitação de produção recém-executados.</p><h2 id="ci-corrections-recovery-and-unfinished-work" tabindex="-1">Correções de CI, recuperação e trabalho inacabado <a class="header-anchor" href="#ci-corrections-recovery-and-unfinished-work" aria-label="Permalink to &quot;Correções de CI, recuperação e trabalho inacabado {#ci-corrections-recovery-and-unfinished-work}&quot;">​</a></h2><p>O código corrige ordenação de módulos de teste, opção explícita de SemVer preliminar em um cenário de ciclo de vida e leitura limitada de cabeçalhos completos em um servidor de teste. A política de compatibilidade de plugins de produção permanece igual. O fluxo de lançamento exige inicialização do AppImage Linux com perfil isolado, verificações de conteúdo dos instaladores, envio imutável, somas de verificação dos downloads e publicação do feed assinado. A <a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43469055839" target="_blank" rel="noreferrer">execução de recuperação</a> gerou instaladores Linux após impedir que a limpeza aninhada do linuxdeploy excluísse o diretório de extração do processo pai. A próxima verificação exigia incorretamente uma classificação de instalação FUSE ao usar extração e execução. As ferramentas de recuperação agora distinguem inicialização extraída de instalação montada; o atualizador nativo ainda rejeita disposições extraídas. A <a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43484544700" target="_blank" rel="noreferrer">única nova execução autorizada</a> passou no empacotamento e nas duas sondagens CLI, depois falhou antes de frontend-ready porque libxkbcommon-x11 não pôde ser carregada. O trabalho restante foi cancelado para evitar gastar minutos em uma publicação que já não poderia prosseguir. A correção instala os pacotes XKB e inclui a biblioteca carregada dinamicamente com suas dependências; verificações locais de carregamento no Ubuntu passam. Uma inicialização completa e corrigida do AppImage e a publicação da versão ainda não foram verificadas; nenhuma outra execução de Actions foi iniciada.</p><p>Até concluir a recuperação de empacotamento e a publicação verificada, use artefatos publicados e siga o <a href="./../user/updates.html">guia de atualizações</a>. Mantenha backups dos perfis; substituir um binário não desfaz migrações de banco de dados. Para falhas de Variables, preserve estado pendente, versão e detalhes de requisição/erro sem dados sensíveis usando <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>.</p><p>Descoberta de apelidos de Teams e convites vinculados a destinatários ainda dependem do backend <code>6a69c99</code> e da migração <code>20261113000001_remote_invitation_recipients.sql</code>. Esta compilação do aplicativo não implanta o backend. Transporte Cloud de Automations, revisões de Overlays, procedência de histórico/branches e o trabalho restante de apresentação de colaboração são separados. O detentor histórico do bloqueio SQLite da LIVE permanece não identificado. Verificações locais/com conta simulada não comprovam sincronização autenticada de produção nem compatibilidade de Teams.</p><p>O <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.2.md" target="_blank" rel="noreferrer">registro original da versão</a> é mantido como evidência datada. Volte ao <a href="./">índice de versões</a>.</p>',17)])])}const v=a(i,[["render",t]]);export{m as __pageData,v as default};
